<section class="page-heading">
    <div><span class="eyebrow">STOCK MONITORING</span><h1>Stock alerts</h1><p class="muted">Review inventory conditions and record the follow-up.</p></div>
    <form method="post" action="<?= e(url('alert-sync')) ?>"><?= \App\Core\Csrf::field() ?><button class="button button-secondary" type="submit">↻ Check stock now</button></form>
