<section class="stat-grid alert-summary"><article class="stat-card stat-accent"><span class="stat-label">Active alerts</span><strong><?= e($counts['active'] ?? 0) ?></strong><span class="stat-note">need your attention</span></article><article class="stat-card stat-warn"><span class="stat-label">Low stock</span><strong><?= e($counts['low'] ?? 0) ?></strong><span class="stat-note">reorder threshold reached</span></article><article class="stat-card stat-danger"><span class="stat-label">Expired</span><strong><?= e($counts['expired'] ?? 0) ?></strong><span class="stat-note">check before dispensing</span></article></section>
<section class="panel">
    <div class="panel-heading"><div><span class="eyebrow">ALERT HISTORY</span><h2>Monitor and resolve</h2></div></div>
    <form method="get" action="<?= e(BASE_URL) ?>/index.php" class="filter-bar">
        <input type="hidden" name="r" value="alerts">
        <label class="filter-select"><span class="sr-only">Alert status</span><select name="status"><option value="active" <?= $status === 'active' ? 'selected' : '' ?>>Active alerts</option><option value="resolved" <?= $status === 'resolved' ? 'selected' : '' ?>>Resolved alerts</option><option value="all" <?= $status === 'all' ? 'selected' : '' ?>>All alerts</option></select></label>
        <label class="filter-select"><span class="sr-only">Alert type</span><select name="type"><option value="">All types</option><option value="low" <?= $type === 'low' ? 'selected' : '' ?>>Low stock</option><option value="expired" <?= $type === 'expired' ? 'selected' : '' ?>>Expired</option></select></label>
        <button class="button button-secondary" type="submit">Filter</button>
        <a class="button button-quiet" href="<?= e(url('alert-form')) ?>">＋ Create alert</a>
    </form>
    <?php if (!$alerts): ?><div class="empty-state empty-compact"><h2>No alerts in this view</h2><p class="muted">Try a different filter, or check stock to generate current alerts.</p><a class="button button-secondary" href="<?= e(url('alerts', ['status' => 'all'])) ?>">View all alerts</a></div><?php else: ?>
        <div class="table-wrap"><table><thead><tr><th>Medicine</th><th>Alert type</th><th>Current stock</th><th>Expiry date</th><th>Triggered</th><th>Status</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach ($alerts as $alert): ?><tr><td class="table-strong"><?= e($alert['medicine_name']) ?></td><td><span class="badge <?= $alert['alert_type'] === 'expired' ? 'badge-danger' : 'badge-warn' ?>"><?= $alert['alert_type'] === 'expired' ? 'Expired' : 'Low stock' ?></span></td><td><?= e($alert['stock']) ?><?= $alert['alert_type'] === 'low' ? ' / ' . e($alert['reorder_level']) : '' ?></td><td><?= e(date('M j, Y', strtotime($alert['expiry_date']))) ?></td><td><?= e(date('M j, Y · H:i', strtotime($alert['triggered_at']))) ?></td><td><?= $alert['resolved'] ? '<span class="badge badge-neutral">Resolved</span>' : '<span class="badge badge-success">Active</span>' ?></td><td><div class="row-actions"><?php if (!$alert['resolved']): ?><form method="post" action="<?= e(url('alert-resolve')) ?>"><?= \App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= e($alert['alert_id']) ?>"><button class="button button-quiet button-small" type="submit">Resolve</button></form><?php endif; ?><form method="post" action="<?= e(url('alert-delete')) ?>" data-confirm="Delete this alert permanently?"><?= \App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= e($alert['alert_id']) ?>"><button class="button button-quiet button-small button-danger-text" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div>
    <?php endif; ?>
</section>
